#!/usr/bin/env python3
"""Embed the trusted Python bootstrap as deterministic C bytes."""

from __future__ import annotations

import argparse
import pathlib


def render(data: bytes) -> str:
    lines = []
    for offset in range(0, len(data), 12):
        chunk = data[offset : offset + 12]
        lines.append("    " + ", ".join(f"0x{byte:02x}" for byte in chunk) + ",")
    body = "\n".join(lines)
    return (
        "/* Generated by embed_bootstrap.py; do not edit. */\n"
        "static const unsigned char shimmy_python_bootstrap[] = {\n"
        f"{body}\n"
        "};\n"
        f"static const unsigned int shimmy_python_bootstrap_len = {len(data)}u;\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("bootstrap_path", type=pathlib.Path)
    parser.add_argument("output_path", type=pathlib.Path)
    args = parser.parse_args()
    bootstrap_path = args.bootstrap_path
    output_path = args.output_path
    data = bootstrap_path.read_bytes()
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(render(data), encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
